export async function createFilingArtifact(db: D1Database, bucket: R2Bucket, input: { tenantId: string; matterId: string; kind: string; content?: string }): Promise<FilingArtifact> { if (!await getMatter(db, input.tenantId, input.matterId)) throw new Error('matter_not_found'); const now = new Date().toISOString(); const id = crypto.randomUUID(); const r2Key = input.content ? `filings/${input.tenantId}/${input.matterId}/${id}.txt` : undefined; if (input.content && r2Key) await bucket.put(r2Key, input.content, { httpMetadata: { contentType: 'text/plain' } }); const artifact: FilingArtifact = { id, tenantId: input.tenantId, matterId: input.matterId, kind: input.kind, status: 'DRAFT', r2Key, blockedReasons: [], gateEvidence: {}, createdAt: now, updatedAt: now }; await db.prepare('INSERT INTO filing_artifacts (id, tenant_id, matter_id, kind, status, r2_key, blocked_reasons_json, payload_json, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(id, artifact.tenantId, artifact.matterId, artifact.kind, artifact.status, artifact.r2Key ?? null, '[]', JSON.stringify(artifact), now, now).run(); return artifact; }
