export async function advanceFilingArtifact(db: D1Database, tenantId: string, matterId: string, artifactId: string, nextStatus: FilingArtifact['status'], blockedReasons: string[], evidenceIds: string[], humanConfirmed: boolean, reviewer?: string): Promise<FilingArtifact> {
  const row = await db.prepare('SELECT payload_json FROM filing_artifacts WHERE id = ? AND tenant_id = ? AND matter_id = ?').bind(artifactId, tenantId, matterId).first<{ payload_json: string }>();
  if (!row) throw new Error('artifact_not_found_or_out_of_scope');
  const artifact = JSON.parse(row.payload_json) as FilingArtifact;
  const sequence: FilingArtifact['status'][] = ['DRAFT', 'FACT_CHECK', 'AUTHORITY_CHECK', 'RED_TEAM', 'BLUE_TEAM', 'PROCEDURAL_CHECK', 'EXHIBIT_CHECK', 'RELIEF_CHECK', 'HUMAN_REVIEW_REQUIRED', 'READY_TO_FILE'];
  const requiredGates: FilingGate[] = ['FACT_CHECK', 'AUTHORITY_CHECK', 'RED_TEAM', 'BLUE_TEAM', 'PROCEDURAL_CHECK', 'EXHIBIT_CHECK', 'RELIEF_CHECK', 'HUMAN_REVIEW_REQUIRED'];
  if (artifact.status === 'BLOCKED' && nextStatus !== 'DRAFT') throw new Error('blocked_artifact_requires_explicit_restart');
  if (nextStatus !== 'BLOCKED' && nextStatus !== 'READY_TO_FILE' && nextStatus !== 'DRAFT' && evidenceIds.length === 0) throw new Error('gate_evidence_required');
  if (nextStatus === 'READY_TO_FILE' && (!humanConfirmed || !reviewer || artifact.status !== 'HUMAN_REVIEW_REQUIRED')) throw new Error('human_review_gate_required');
  if (nextStatus === 'READY_TO_FILE' && !requiredGates.every((gate) => Array.isArray(artifact.gateEvidence?.[gate]) && artifact.gateEvidence[gate]!.length > 0)) throw new Error('all_review_gate_evidence_required');
  if (nextStatus !== 'BLOCKED' && nextStatus !== 'DRAFT') {
    const evidenceToVerify = nextStatus === 'READY_TO_FILE'
      ? Object.values(artifact.gateEvidence ?? {}).flat()
      : evidenceIds;
    await assertFilingEvidence(db, tenantId, matterId, evidenceToVerify);
  }
  if (nextStatus !== 'BLOCKED' && artifact.status !== 'BLOCKED' && nextStatus !== 'READY_TO_FILE' && sequence.indexOf(nextStatus) !== sequence.indexOf(artifact.status) + 1) throw new Error('invalid_filing_transition');
  const gateEvidence = nextStatus === 'DRAFT' ? {} : nextStatus !== 'BLOCKED' && nextStatus !== 'READY_TO_FILE' ? { ...(artifact.gateEvidence ?? {}), [nextStatus]: [...new Set(evidenceIds)] } : artifact.gateEvidence ?? {};
  const updated = { ...artifact, status: nextStatus, blockedReasons, gateEvidence, updatedAt: new Date().toISOString() };
  const statements = [
    db.prepare('UPDATE filing_artifacts SET status = ?, blocked_reasons_json = ?, payload_json = ?, updated_at = ? WHERE id = ? AND tenant_id = ? AND matter_id = ?').bind(updated.status, JSON.stringify(blockedReasons), JSON.stringify({ ...updated, reviewer: nextStatus === 'READY_TO_FILE' ? reviewer : undefined }), updated.updatedAt, artifactId, tenantId, matterId),
    db.prepare('INSERT INTO filing_gate_events (tenant_id, matter_id, artifact_id, from_status, to_status, evidence_ids_json, blocked_reasons_json, reviewer, human_confirmed) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(tenantId, matterId, artifactId, artifact.status, nextStatus, JSON.stringify(evidenceIds), JSON.stringify(blockedReasons), reviewer ?? null, humanConfirmed ? 1 : 0),
  ];
  await db.batch(statements);
  return updated;
}
