export async function listAuthorityEdges(db: D1Database, tenantId: string, judgeId: string, matterId?: string): Promise<AuthorityEdge[]> { const scope = matterId ? 'AND (a.matter_id IS NULL OR a.matter_id = ?) AND (b.matter_id IS NULL OR b.matter_id = ?)' : 'AND a.matter_id IS NULL AND b.matter_id IS NULL'; const query = matterId ? db.prepare(`SELECT e.payload_json FROM authority_edges e JOIN authority_records a ON a.id = e.from_authority_id AND a.tenant_id = e.tenant_id JOIN authority_records b ON b.id = e.to_authority_id AND b.tenant_id = e.tenant_id WHERE e.tenant_id = ? AND a.judge_id = ? AND b.judge_id = ? ${scope} ORDER BY e.created_at DESC`).bind(tenantId, judgeId, judgeId, matterId, matterId) : db.prepare(`SELECT e.payload_json FROM authority_edges e JOIN authority_records a ON a.id = e.from_authority_id AND a.tenant_id = e.tenant_id JOIN authority_records b ON b.id = e.to_authority_id AND b.tenant_id = e.tenant_id WHERE e.tenant_id = ? AND a.judge_id = ? AND b.judge_id = ? ${scope} ORDER BY e.created_at DESC`).bind(tenantId, judgeId, judgeId); const rows = await query.all<{ payload_json: string }>(); return rows.results.map((row) => JSON.parse(row.payload_json) as AuthorityEdge); }
export async function reviewAuthorityRecord(db: D1Database, tenantId: string, judgeId: string, input: { authorityId: string; reviewer: string; decision: AuthorityRecord['status']; notes: string; verificationSourceUrl?: string; verificationSourceHash?: string }): Promise<void> { if (!input.verificationSourceUrl && !input.verificationSourceHash) throw new Error('verification_evidence_required'); const row = await db.prepare('SELECT payload_json FROM authority_records WHERE id = ? AND tenant_id = ? AND judge_id = ?').bind(input.authorityId, tenantId, judgeId).first<{ payload_json: string }>(); if (!row) throw new Error('authority_not_found_or_out_of_scope'); const record = JSON.parse(row.payload_json) as AuthorityRecord; if (input.decision === 'VERIFIED') await assertSourceVerified(db, tenantId, record.sourceId, judgeId); record.status = input.decision; if (input.decision === 'VERIFIED') record.verifiedAt = new Date().toISOString(); await db.batch([db.prepare('UPDATE authority_records SET status = ?, verified_at = ?, payload_json = ? WHERE id = ? AND tenant_id = ? AND judge_id = ?').bind(record.status, record.verifiedAt ?? null, JSON.stringify(record), input.authorityId, tenantId, judgeId), db.prepare('INSERT INTO authority_review_events (id, tenant_id, authority_id, reviewer, decision, notes, verification_source_url, verification_source_hash) VALUES (NULL, ?, ?, ?, ?, ?, ?, ?)').bind(tenantId, input.authorityId, input.reviewer, input.decision, input.notes, input.verificationSourceUrl ?? null, input.verificationSourceHash ?? null)]); }
export async function addAuthorityEdge(db: D1Database, input: Omit<AuthorityEdge, 'id' | 'status' | 'createdAt'> & { judgeId: string }): Promise<AuthorityEdge> { const rows = await db.prepare('SELECT id, judge_id, matter_id FROM authority_records WHERE id IN (?, ?) AND tenant_id = ?').bind(input.fromAuthorityId, input.toAuthorityId, input.tenantId).all<{ id: string; judge_id: string; matter_id: string | null }>(); if (rows.results.length !== 2 || rows.results.some((row) => row.judge_id !== input.judgeId) || rows.results[0]!.judge_id !== rows.results[1]!.judge_id || (rows.results[0]!.matter_id && rows.results[1]!.matter_id && rows.results[0]!.matter_id !== rows.results[1]!.matter_id)) throw new Error('authority_edge_out_of_scope'); await assertSourceScope(db, input.tenantId, input.sourceId, input.judgeId); const { judgeId: _judgeId, ...edgeInput } = input; const edge: AuthorityEdge = { ...edgeInput, id: crypto.randomUUID(), status: 'UNVERIFIED', createdAt: new Date().toISOString() }; await db.prepare('INSERT INTO authority_edges (id, tenant_id, from_authority_id, to_authority_id, relationship, evidence_note, source_id, status, created_at, payload_json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)').bind(edge.id, edge.tenantId, edge.fromAuthorityId, edge.toAuthorityId, edge.relationship, edge.evidenceNote, edge.sourceId ?? null, edge.status, edge.createdAt, JSON.stringify(edge)).run(); return edge; }
export async function reviewAuthorityEdge(db: D1Database, tenantId: string, judgeId: string, input: { edgeId: string; reviewer: string; decision: 'VERIFIED' | 'DISPUTED'; notes: string; verificationSourceUrl?: string; verificationSourceHash?: string }): Promise<void> { if (!input.verificationSourceUrl && !input.verificationSourceHash) throw new Error('verification_evidence_required'); const row = await db.prepare('SELECT e.payload_json FROM authority_edges e JOIN authority_records a ON a.id = e.from_authority_id AND a.tenant_id = e.tenant_id JOIN authority_records b ON b.id = e.to_authority_id AND b.tenant_id = e.tenant_id WHERE e.id = ? AND e.tenant_id = ? AND a.judge_id = ? AND b.judge_id = ? AND (a.matter_id IS NULL OR b.matter_id IS NULL OR a.matter_id = b.matter_id)').bind(input.edgeId, tenantId, judgeId, judgeId).first<{ payload_json: string }>(); if (!row) throw new Error('authority_edge_not_found_or_out_of_scope'); const edge = JSON.parse(row.payload_json) as AuthorityEdge; if (input.decision === 'VERIFIED') await assertSourceVerified(db, tenantId, edge.sourceId, judgeId); edge.status = input.decision; await db.batch([db.prepare('UPDATE authority_edges SET status = ?, payload_json = ? WHERE id = ? AND tenant_id = ?').bind(edge.status, JSON.stringify(edge), input.edgeId, tenantId), db.prepare('INSERT INTO authority_edge_reviews (tenant_id, edge_id, reviewer, decision, notes, verification_source_url, verification_source_hash) VALUES (?, ?, ?, ?, ?, ?, ?)').bind(tenantId, input.edgeId, input.reviewer, input.decision, input.notes, input.verificationSourceUrl ?? null, input.verificationSourceHash ?? null)]); }
export async function reviewJudgeIdentity(db: D1Database, tenantId: string, judgeId: string, input: { reviewer: string; decision: JudgeProfileIdentity['status']; notes: string; verificationSourceUrl?: string; verificationSourceHash?: string }): Promise<void> { if (input.decision !== 'NEEDS_VERIFICATION' && !input.verificationSourceUrl && !input.verificationSourceHash) throw new Error('verification_evidence_required'); const identity = await getJudgeIdentity(db, tenantId, judgeId); if (!identity) throw new Error('identity_not_found_or_out_of_scope'); identity.status = input.decision; if (input.decision === 'CURRENT') identity.lastVerified = new Date().toISOString(); await db.batch([db.prepare('UPDATE judge_profiles SET status = ?, last_verified = ?, payload_json = ? WHERE tenant_id = ? AND judge_id = ?').bind(identity.status, identity.lastVerified, JSON.stringify(identity), tenantId, judgeId), db.prepare('INSERT INTO judge_profile_reviews (tenant_id, judge_id, reviewer, decision, notes, verification_source_url, verification_source_hash) VALUES (?, ?, ?, ?, ?, ?, ?)').bind(tenantId, judgeId, input.reviewer, input.decision, input.notes, input.verificationSourceUrl ?? null, input.verificationSourceHash ?? null)]); }
export async function listJudgeProfileReviews(db: D1Database, tenantId: string, judgeId: string): Promise<Array<Record<string, unknown>>> { const rows = await db.prepare('SELECT id, prediction_id, reviewer, decision, notes, verification_source_url, verification_source_hash, created_at FROM judge_profile_reviews WHERE tenant_id = ? AND judge_id = ? ORDER BY id ASC').bind(tenantId, judgeId).all<Record<string, unknown>>(); return rows.results; }
